function pngU32(b, off){ return ((b[off]<<24)|(b[off+1]<<16)|(b[off+2]<<8)|b[off+3])>>>0; }
function pngParse(bytes){
  var r={valid:false, chunks:[], width:0, height:0, bitDepth:0, colorType:0, colorTypeDesc:'',
         compression:0, filter:0, interlace:0, metadata:{}, hasPalette:false, hasIcc:false, error:''};
  if(!bytes || bytes.length<24){ r.error='文件过短'; return r; }
  var sig=[137,80,78,71,13,10,26,10];
  for(var i=0;i<8;i++){ if(bytes[i]!==sig[i]){ r.error='PNG 签名不符'; return r; } }
  var p=8;
  while(p+8<=bytes.length){
    var len=pngU32(bytes,p);
    var type=String.fromCharCode(bytes[p+4],bytes[p+5],bytes[p+6],bytes[p+7]);
    var ds=p+8, de=ds+len;
    r.chunks.push({type:type, length:len});
    if(type==='IHDR'){
      r.width=pngU32(bytes,ds);
      r.height=pngU32(bytes,ds+4);
      r.bitDepth=bytes[ds+8]; r.colorType=bytes[ds+9]; r.compression=bytes[ds+10];
      r.filter=bytes[ds+11]; r.interlace=bytes[ds+12];
      var ct={0:'灰度',2:'RGB',3:'索引色',4:'灰度+Alpha',6:'RGBA'};
      r.colorTypeDesc=ct[r.colorType]||('未知'+r.colorType);
    } else if(type==='PLTE'){ r.hasPalette=true; }
    else if(type==='iCCP'){ r.hasIcc=true; }
    else if(type==='tEXt'){
      var s=''; for(var k=ds;k<de;k++) s+=String.fromCharCode(bytes[k]);
      var idx=s.indexOf('\u0000'); if(idx>=0) r.metadata[s.slice(0,idx)]=s.slice(idx+1);
    } else if(type==='iTXt'){
      var s2=''; for(var k2=ds;k2<de;k2++) s2+=String.fromCharCode(bytes[k2]);
      var i0=s2.indexOf('\u0000');
      if(i0>=0){ var key=s2.slice(0,i0), rest=s2.slice(i0+1);
        var n1=rest.indexOf('\u0000',1);
        if(n1>=0){ var n2=rest.indexOf('\u0000',n1+1); if(n2>=0) r.metadata[key]=rest.slice(n2+1); }
      }
    }
    p=de+4; if(type==='IEND') break; if(p>bytes.length) break;
  }
  if(r.width>0 && r.height>0) r.valid=true;
  return r;
}
function pngBytesFromInput(arr){ return (arr instanceof Uint8Array)?arr:Uint8Array.from(arr); }
